import{_ as t,c as o,o as r,a5 as c}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"Feed 系统：推荐、关注、用户 Feed","description":"","frontmatter":{"title":"Feed 系统：推荐、关注、用户 Feed","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#3.3","branch":"main","level":1,"order":3.3},"headers":[],"relativePath":"posts/projects/zfeed/03-content-rpc-service/03-feed-systems-recommend-follow-user-feeds.md","filePath":"posts/projects/zfeed/03-content-rpc-service/03-feed-systems-recommend-follow-user-feeds.md","lastUpdated":1779632679000}'),l={name:"posts/projects/zfeed/03-content-rpc-service/03-feed-systems-recommend-follow-user-feeds.md"};function n(i,e,a,d,p,f){return r(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="feed-系统-推荐、关注、用户-feed" tabindex="-1">Feed 系统：推荐、关注、用户 Feed <a class="header-anchor" href="#feed-系统-推荐、关注、用户-feed" aria-label="Permalink to &quot;Feed 系统：推荐、关注、用户 Feed&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/backfillfollowinboxlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/backfillfollowinboxlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/contentservice_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/contentservice_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editarticlelogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editarticlelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editvideologic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editvideologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feed_bench_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feed_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feeditembuilder.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feeditembuilder.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feeditembuilder_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feeditembuilder_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/followfeedlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/followfeedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/followfeedlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/followfeedlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userfavoritefeedlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userfavoritefeedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userfavoritefeedlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userfavoritefeedlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userpublishfeedlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userpublishfeedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userpublishfeedlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userpublishfeedlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_bench_test.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer_bench_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/README.md?plain=1" target="_blank" rel="noreferrer">bench/data/README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/content_ids.csv" target="_blank" rel="noreferrer">bench/data/small/content_ids.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/follow_edges.csv" target="_blank" rel="noreferrer">bench/data/small/follow_edges.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/search_terms.csv" target="_blank" rel="noreferrer">bench/data/small/search_terms.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/tokens.json" target="_blank" rel="noreferrer">bench/data/small/tokens.json</a></li></ul></details><p>本文说明 <code>content-rpc</code> 服务中四种主要 Feed 类型的实现。这些系统结合 Redis Sorted Set（ZSet）实现高性能索引，使用 Lua 脚本实现原子分页，并通过补全流水线组装丰富的内容元数据。</p><h2 id="feed-类型概览" tabindex="-1">Feed 类型概览 <a class="header-anchor" href="#feed-类型概览" aria-label="Permalink to &quot;Feed 类型概览&quot;">​</a></h2><p>系统按照分发模型和可见性规则对 Feed 进行分类：</p><table tabindex="0"><thead><tr><th>Feed 类型</th><th>模型</th><th>存储实体</th><th>分页 cursor</th></tr></thead><tbody><tr><td>推荐（热门）</td><td>拉取（快照）</td><td><code>hot_feed</code> ZSet</td><td>内容 ID（来自 ZSet score）</td></tr><tr><td>关注收件箱</td><td>推送（Fan-out）</td><td><code>follow_inbox:{uid}</code> ZSet</td><td>内容 ID</td></tr><tr><td>用户发布</td><td>拉取（按需）</td><td><code>user_publish:{uid}</code> ZSet</td><td>内容 ID</td></tr><tr><td>用户收藏</td><td>拉取（按需）</td><td><code>user_favorite:{uid}</code> ZSet</td><td>收藏 ID（来自 ZSet score）</td></tr></tbody></table><h3 id="feed-系统架构" tabindex="-1">Feed 系统架构 <a class="header-anchor" href="#feed-系统架构" aria-label="Permalink to &quot;Feed 系统架构&quot;">​</a></h3><p>下图展示 <code>FeedItemBuilder</code> 和各类 <code>Logic</code> 如何与 Redis 及其他 RPC 服务交互，以完成 Feed 请求。</p><p>Feed 读取与补全流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go#L32-L46" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go#32-46</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/followfeedlogic.go#L28-L44" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/followfeedlogic.go#28-44</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feeditembuilder.go#L1-L50" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feeditembuilder.go#1-50</a></p><hr><h2 id="推荐-feed-热门-feed" tabindex="-1">推荐 Feed（热门 Feed） <a class="header-anchor" href="#推荐-feed-热门-feed" aria-label="Permalink to &quot;推荐 Feed（热门 Feed）&quot;">​</a></h2><p>推荐 Feed 提供全局排序的“热门”内容列表。为了保证稳定分页（防止分数变化时内容跨页跳动），它使用快照机制。</p><h3 id="实现细节" tabindex="-1">实现细节 <a class="header-anchor" href="#实现细节" aria-label="Permalink to &quot;实现细节&quot;">​</a></h3><ul><li>快照选择：逻辑首先从请求中解析 <code>SnapshotId</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go#L101-L110" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go#101-110</a> 如果请求未提供，则使用 <code>hot_feed:latest</code> 中存储的最新全局快照 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go#L138-L140" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go#138-140</a></li><li>Lua 脚本：使用 <code>QueryHotFeedZSetScript</code> 原子检查快照是否存在，并获取一页 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go#L133-L145" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go#133-145</a></li><li>回退：如果请求的快照已经过期，系统会回退到实时的 <code>hot_feed</code> ZSet。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#L1-L20" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#1-20</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go#L48-L99" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go#48-99</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#L151-L182" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#151-182</a></p><hr><h2 id="关注收件箱-推模型" tabindex="-1">关注收件箱（推模型） <a class="header-anchor" href="#关注收件箱-推模型" aria-label="Permalink to &quot;关注收件箱（推模型）&quot;">​</a></h2><p>关注 Feed 使用基于推送的“收件箱”模型：内容发布时，会 fan-out 到粉丝各自的 Redis ZSet 中。</p><h3 id="cache-aside-与重建" tabindex="-1">Cache-Aside 与重建 <a class="header-anchor" href="#cache-aside-与重建" aria-label="Permalink to &quot;Cache-Aside 与重建&quot;">​</a></h3><p>如果用户的 <code>follow_inbox</code> 缓存缺失（例如被淘汰或新登录），系统会触发重建：</p><ol><li>分布式锁：使用 <code>gzredis.NewRedisLock</code> 获取锁，锁 key 为 <code>follow_inbox:lock:{uid}</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/followfeedlogic.go#L106-L110" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/followfeedlogic.go#106-110</a></li><li>数据读取：系统调用 <code>FollowRpc.ListFollowees</code>，找出用户关注的所有作者。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/followfeedlogic.go#L243-L260" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/followfeedlogic.go#243-260</a></li><li>数据库获取：从这些作者中读取最新 <code>FeedKeepLatestN</code> 条内容（默认 1000）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/followfeedlogic.go#L229-L232" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/followfeedlogic.go#229-232</a></li><li>缓存预热：填充 Redis ZSet，并释放锁。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/followfeedlogic.go#L117-L121" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/followfeedlogic.go#117-121</a></li></ol><h3 id="回填机制" tabindex="-1">回填机制 <a class="header-anchor" href="#回填机制" aria-label="Permalink to &quot;回填机制&quot;">​</a></h3><p>当用户新关注一个作者时，会触发 <code>BackfillFollowInbox</code> 逻辑，将该作者最近发布的内容拉取到关注者收件箱中。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/backfillfollowinboxlogic_test.go#L22-L78" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/backfillfollowinboxlogic_test.go#22-78</a></p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/followfeedlogic.go#L97-L139" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/followfeedlogic.go#97-139</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/followfeedlogic_test.go#L131-L172" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/followfeedlogic_test.go#131-172</a></p><hr><h2 id="用户发布与收藏-feed" tabindex="-1">用户发布与收藏 Feed <a class="header-anchor" href="#用户发布与收藏-feed" aria-label="Permalink to &quot;用户发布与收藏 Feed&quot;">​</a></h2><p>这些 Feed 基于拉取模型，并且与单个用户的动作相关。</p><h3 id="用户发布-feed" tabindex="-1">用户发布 Feed <a class="header-anchor" href="#用户发布-feed" aria-label="Permalink to &quot;用户发布 Feed&quot;">​</a></h3><ul><li>索引：存储在 <code>user_publish:{uid}</code>。</li><li>维护：在 <code>Publish</code> 流程中更新，并在 <code>DeleteContent</code> 期间清理。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L114-L114" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#114</a></li><li>一致性：缓存缺失时，使用类似关注收件箱的“加锁重建”模式。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userpublishfeedlogic.go#L103-L146" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userpublishfeedlogic.go#103-146</a></li></ul><h3 id="用户收藏-feed" tabindex="-1">用户收藏 Feed <a class="header-anchor" href="#用户收藏-feed" aria-label="Permalink to &quot;用户收藏 Feed&quot;">​</a></h3><ul><li>索引：存储在 <code>user_favorite:{uid}</code>。</li><li>计分：不同于其他使用 <code>ContentID</code> 或 <code>Timestamp</code> 作为 ZSet score 的 Feed，该 Feed 使用 <code>FavoriteID</code> 作为 score，确保列表按照用户收藏时间排序。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userfavoritefeedlogic_test.go#L53-L55" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userfavoritefeedlogic_test.go#53-55</a></li><li>数据补全：调用 <code>FavoriteRpc.QueryFavoriteList</code>，从 <code>interaction-rpc</code> 服务重建缓存。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userfavoritefeedlogic.go#L221-L250" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userfavoritefeedlogic.go#221-250</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userpublishfeedlogic.go#L44-L84" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userpublishfeedlogic.go#44-84</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/userfavoritefeedlogic.go#L35-L75" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/userfavoritefeedlogic.go#35-75</a></p><hr><h2 id="feeditembuilder-补全流水线" tabindex="-1">FeedItemBuilder 补全流水线 <a class="header-anchor" href="#feeditembuilder-补全流水线" aria-label="Permalink to &quot;FeedItemBuilder 补全流水线&quot;">​</a></h2><p><code>FeedItemBuilder</code> 是一个共享工具，负责将原始 ID 转换为完整补全的 <code>ContentItem</code> 对象。</p><h3 id="补全步骤" tabindex="-1">补全步骤 <a class="header-anchor" href="#补全步骤" aria-label="Permalink to &quot;补全步骤&quot;">​</a></h3><ol><li>批量加载：从 MySQL（<code>zfeed_content</code>）加载基础内容元数据，并联接具体表（<code>zfeed_article</code> 或 <code>zfeed_video</code>）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feeditembuilder.go#L50-L80" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feeditembuilder.go#50-80</a></li><li>互动状态：如果提供了 <code>ViewerId</code>，则调用 <code>interaction-rpc</code>（<code>BatchIsLiked</code>）判断当前用户是否点赞了这些内容。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feeditembuilder_test.go#L82-L113" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feeditembuilder_test.go#82-113</a></li><li>Protobuf 映射：将内部模型映射为 <code>contentpb.ContentItem</code> gRPC 消息格式。</li></ol><p>代码实体关系</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feeditembuilder.go#L1-L45" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feeditembuilder.go#1-45</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feeditembuilder_test.go#L19-L46" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feeditembuilder_test.go#19-46</a></p><hr><h2 id="删除时的索引清理" tabindex="-1">删除时的索引清理 <a class="header-anchor" href="#删除时的索引清理" aria-label="Permalink to &quot;删除时的索引清理&quot;">​</a></h2><p>通过 <code>DeleteContentLogic</code> 删除内容时，系统会执行多索引清理，确保该内容立即从所有 Feed 中消失。</p><h3 id="清理例程-cleanupindexes" tabindex="-1">清理例程（<code>cleanupIndexes</code>） <a class="header-anchor" href="#清理例程-cleanupindexes" aria-label="Permalink to &quot;清理例程（`cleanupIndexes`）&quot;">​</a></h3><p><code>cleanupIndexes</code> 函数执行以下操作：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L108-L118" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#108-118</a></p><ol><li>用户发布 Feed：从作者的发布 ZSet 中移除。</li><li>关注收件箱：查询作者粉丝，并从每个粉丝的 Redis 收件箱中移除该 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L120-L142" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#120-142</a></li><li>收藏 Feed：查询收藏过该内容的用户，并从他们的收藏 ZSet 中移除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L148-L170" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#148-170</a></li><li>热门索引：从实时热门 Feed 和当前活跃快照中移除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L172-L186" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#172-186</a></li></ol><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L31-L106" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#31-106</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L188-L192" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#188-192</a></p>',47)])])}const h=t(l,[["render",n]]);export{b as __pageData,h as default};
